import json
import re
import datetime

# Only cancellations made in the last 48 hours are offered a new time. Without this, the first run against
# a practice (empty seen file) would raise an item for every historic cancellation Cliniko returns.
RECENT_HOURS = 48


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def extract_id(link):
    if not isinstance(link, dict):
        return ""
    url = ((link.get("links") or {}).get("self")) or ""
    m = re.search(r"/(\d+)(?:$|\?)", str(url))
    return m.group(1) if m else ""


def parse_iso(iso):
    try:
        dt = datetime.datetime.fromisoformat(str(iso or "").replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except Exception:
        return None


practices = []
try:
    entries = api.files.list(path="PracticeManager/Practices", scope="org")
except Exception:
    entries = []
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    slug = str(fname)[:-5]
    practice = read_json("PracticeManager/Practices/" + fname, {}) or {}
    if practice:
        practices.append({"slug": slug, "practice": practice})

now = datetime.datetime.now(datetime.timezone.utc)
new_items = []
for p in practices:
    business_id = str(p["practice"].get("cliniko_business_id") or "")
    if not business_id:
        continue
    seen = read_json("PracticeManager/CancellationSeen/" + p["slug"] + ".json", []) or []
    seen_ids = {str(x) for x in seen}
    try:
        result = api.connectors.invoke(
            server="cliniko-scheduling", tool="list_individual_appointments",
            # cancelled_at:* is required - Cliniko excludes cancelled appointments by default, so without
            # this the query returns none at all (the same bug cliniko-automations' gap filler hit, fixed
            # in its PR #1217). Sort by updated_at, not starts_at: we want the most recently CANCELLED
            # first, which starts_at (the original appointment time) doesn't tell us.
            args={"q": ["business_id:=" + business_id, "cancelled_at:*"], "sort": "updated_at:desc", "per_page": 50},
        )
        rows = (result or {}).get("individual_appointments") or []
    except Exception:
        rows = []
    for row in rows:
        appt_id = str(row.get("id") or "")
        if not appt_id or appt_id in seen_ids:
            continue
        cancelled_at = parse_iso(row.get("cancelled_at"))
        if not cancelled_at or (now - cancelled_at).total_seconds() > RECENT_HOURS * 3600:
            continue
        starts_at = parse_iso(row.get("starts_at"))
        if not starts_at or starts_at <= now:
            continue
        # cliniko-automations' email reschedule desk cancels with the note "Patient cancelled by email; ..."
        # after it has already replied to the patient in their own thread - offering times again from here
        # would contact the same patient twice about the same cancellation.
        if "cancelled by email" in str(row.get("cancellation_note") or "").lower():
            continue
        new_items.append({
            "slug": p["slug"], "practice": p["practice"], "appointment_id": appt_id,
            "patient_name": row.get("patient_name") or "",
            "patient_id": extract_id(row.get("patient")),
            "practitioner_id": extract_id(row.get("practitioner")),
            "business_id": business_id,
            "appointment_type_id": extract_id(row.get("appointment_type")),
            "starts_at": row.get("starts_at") or "",
            "ends_at": row.get("ends_at") or "",
        })

import json
import re
import datetime
from zoneinfo import ZoneInfo

AI_PROMPT = (
    "You are drafting a short, warm email on behalf of a healthcare clinic to a patient who just cancelled their "
    "appointment. Offer the available times given, as a numbered list, written exactly as given, and ask them to "
    "reply with the number of the time that suits. Write in the tone instructed. Never give clinical advice, "
    "diagnosis or interpretation. Keep it under 120 words."
)
AI_HINT = '{"subject": "", "body": ""}'
SOURCE = "automation:AU-05 Cancellation reschedule offer"
MAX_OFFERED = 3
MIN_NOTICE_HOURS = 2


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def extract_link_id(link):
    if not isinstance(link, dict):
        return ""
    m = re.search(r"/(\d+)(?:$|\?)", str(((link.get("links") or {}).get("self")) or ""))
    return m.group(1) if m else ""


def parse_iso(iso):
    try:
        dt = datetime.datetime.fromisoformat(str(iso or "").replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except Exception:
        return None


def audit(slug, tz, action, target, summary, workq_item_id="", guardrails=None):
    # SK-13 format (healthcare-practice-management-foundation): one JSON line per action, practice-local ts.
    now_local = datetime.datetime.now(tz)
    path = "PracticeManager/AuditLog/" + slug + "-" + now_local.strftime("%Y-%m-%d") + ".jsonl"
    line = {
        "ts": now_local.isoformat(timespec="seconds"), "practice_slug": slug, "actor": "agent",
        "source": SOURCE, "action": action, "target": target, "summary": summary,
    }
    if guardrails:
        line["guardrails"] = guardrails
    if workq_item_id:
        line["workq_item_id"] = workq_item_id
    try:
        try:
            existing = api.files.read(file=path) or ""
        except Exception:
            existing = ""
        if existing and not existing.endswith("\n"):
            existing += "\n"
        api.files.put(file=path, content=existing + json.dumps(line, sort_keys=True) + "\n")
    except Exception:
        pass


item = params.get("item") or {}
slug = item.get("slug") or ""
practice = item.get("practice") or {}
appointment_id = item.get("appointment_id") or ""
patient_id = item.get("patient_id") or ""
patient_name = item.get("patient_name") or "this patient"
outcome = "skipped"

try:
    tz_name = practice.get("timezone") or "Australia/Sydney"
    tz = ZoneInfo(tz_name)
except Exception:
    tz_name = "UTC"
    tz = datetime.timezone.utc


def format_local(iso):
    dt = parse_iso(iso)
    if not dt:
        return str(iso or "")
    return dt.astimezone(tz).strftime("%a %d %b, %I:%M %p").replace(" 0", " ")


if slug and appointment_id:
    seen_path = "PracticeManager/CancellationSeen/" + slug + ".json"
    seen = [str(x) for x in (read_json(seen_path, []) or [])]
    if appointment_id not in seen:
        seen.append(appointment_id)
    write_json(seen_path, seen[-500:])

    policy = practice.get("policy") or {}
    window_hours = policy.get("cancellation_window_hours") or 24
    starts_at = parse_iso(item.get("starts_at"))
    now = datetime.datetime.now(datetime.timezone.utc)
    hours_until = ((starts_at - now).total_seconds() / 3600.0) if starts_at else None
    reviewer = practice.get("reviewer_id") or ""
    cancelled_display = format_local(item.get("starts_at"))

    if hours_until is None or hours_until < window_hours:
        # Inside the cancellation window - per policy this isn't auto-offered a new slot; flag it for the
        # practitioner's own judgement instead.
        alert = api.workq.create(
            title="Late cancellation: " + patient_name,
            scope="org",
            description=(
                patient_name + " cancelled their " + cancelled_display + " appointment inside the "
                + str(window_hours) + "-hour cancellation window. Per policy this isn't auto-offered a new slot - "
                "handle by hand."
            ),
            priority="normal",
            assignee_ids=[reviewer] if reviewer else None,
            labels=["healthcare-practice-management", "cancellation", "late-cancellation"],
        )
        audit(slug, tz, "blocked", {"kind": "appointment", "id": appointment_id},
              "Flagged a late cancellation by " + patient_name + " instead of offering a new time",
              (alert or {}).get("id") or "",
              [{"rule": "cancellation_window", "result": "block", "detail": "inside the " + str(window_hours) + "-hour window"}])
        outcome = "flagged_late_cancellation"
    else:
        email = ""
        if patient_id:
            try:
                patient = api.connectors.invoke(server="cliniko-patients", tool="get_patient", args={"id": patient_id})
                email = (patient or {}).get("email") or ""
            except Exception:
                email = ""

        practitioner_id = item.get("practitioner_id") or ""
        business_id = item.get("business_id") or ""
        appointment_type_id = item.get("appointment_type_id") or ""

        # Practitioner's working hours, used to drop any time Cliniko offers outside them. Fails open (no
        # filter) when no availability data comes back - same rule as cliniko-automations' reschedule desk.
        # Practitioner's working hours, used to drop any time Cliniko offers outside them. Filtered with q[]
        # (plain business_id/practitioner_id params aren't reliable filters) and re-checked per record, and
        # read in the availability's own timezone. Only the time-of-day span is used: Cliniko's open times
        # already respect which days are worked, and its day_of_week numbering isn't documented. Fails open
        # (no filter) when nothing comes back.
        hours_span = None
        hours_tz = tz
        if practitioner_id and business_id:
            try:
                avail_result = api.connectors.invoke(
                    server="cliniko-scheduling", tool="list_daily_availabilities",
                    args={"q": ["business_id:=" + business_id, "practitioner_id:=" + practitioner_id], "per_page": 100},
                )
                starts, ends = [], []
                for rec in (avail_result or {}).get("daily_availabilities") or []:
                    if extract_link_id(rec.get("practitioner")) not in ("", practitioner_id):
                        continue
                    if extract_link_id(rec.get("business")) not in ("", business_id):
                        continue
                    if rec.get("time_zone_identifier"):
                        try:
                            hours_tz = ZoneInfo(str(rec["time_zone_identifier"]))
                        except Exception:
                            pass
                    for block in rec.get("availabilities") or []:
                        b_start = str(block.get("starts_at") or "")[-5:]
                        b_end = str(block.get("ends_at") or "")[-5:]
                        if re.match(r"^\d\d:\d\d$", b_start) and re.match(r"^\d\d:\d\d$", b_end):
                            starts.append(b_start)
                            ends.append(b_end)
                if starts and ends:
                    hours_span = (min(starts), max(ends))
            except Exception:
                hours_span = None

        def within_hours(dt):
            if hours_span is None:
                return True
            hhmm = dt.astimezone(hours_tz).strftime("%H:%M")
            return hours_span[0] <= hhmm < hours_span[1]

        # get_available_times requires from/to dates no more than 7 days apart: look at this week, then
        # the next if this week doesn't have enough. One time per day first, so the patient gets a spread.
        candidates = []
        if practitioner_id and business_id and appointment_type_id:
            today = now.astimezone(tz).date()
            earliest = now + datetime.timedelta(hours=MIN_NOTICE_HOURS)
            for week in range(2):
                if len(candidates) >= MAX_OFFERED * 3:
                    break
                start_day = today + datetime.timedelta(days=7 * week)
                try:
                    avail = api.connectors.invoke(
                        server="cliniko-scheduling", tool="get_available_times",
                        args={
                            "business_id": business_id, "practitioner_id": practitioner_id,
                            "appointment_type_id": appointment_type_id,
                            "from_time": start_day.isoformat(),
                            "to_time": (start_day + datetime.timedelta(days=6)).isoformat(),
                        },
                    )
                    raw_times = (avail or {}).get("available_times") or []
                except Exception:
                    raw_times = []
                for s in raw_times:
                    iso = str((s.get("appointment_start") if isinstance(s, dict) else s) or "")
                    dt = parse_iso(iso)
                    if dt is not None and dt >= earliest and within_hours(dt) and iso not in [c[1] for c in candidates]:
                        candidates.append((dt, iso))
        # candidates are (datetime, original ISO string) pairs, so sorting never compares None
        candidates.sort(key=lambda c: c[0])
        # One time per day, the one closest to when the cancelled appointment was (a 9:15 AM patient is
        # offered mornings around 9, not the first slot of the day), earliest days first.
        target = parse_iso(item.get("starts_at"))
        target_minutes = (target.astimezone(tz).hour * 60 + target.astimezone(tz).minute) if target is not None else 9 * 60

        def distance(c):
            local = c[0].astimezone(tz)
            return abs(local.hour * 60 + local.minute - target_minutes)

        best_per_day = {}
        for c in candidates:
            day = c[0].astimezone(tz).date()
            if day not in best_per_day or distance(c) < distance(best_per_day[day]):
                best_per_day[day] = c
        picked = [best_per_day[d] for d in sorted(best_per_day)][:MAX_OFFERED]
        for c in sorted(candidates, key=distance):
            if len(picked) >= MAX_OFFERED:
                break
            if c not in picked:
                picked.append(c)
        picked.sort(key=lambda c: c[0])
        offered = [c[1] for c in picked]
        offered_display = [format_local(x) for x in offered]

        if not offered:
            alert = api.workq.create(
                title="Cancellation, no open times to offer: " + patient_name,
                scope="org",
                description=(
                    patient_name + " cancelled their " + cancelled_display + " appointment. Cliniko shows no open "
                    "times for the same practitioner and appointment type in the next two weeks, so no offer was "
                    "drafted - follow up by hand."
                ),
                priority="normal",
                assignee_ids=[reviewer] if reviewer else None,
                labels=["healthcare-practice-management", "cancellation"],
            )
            audit(slug, tz, "blocked", {"kind": "appointment", "id": appointment_id},
                  "No open times to offer " + patient_name + " after their cancellation; flagged for follow-up",
                  (alert or {}).get("id") or "")
            outcome = "flagged_no_times"
        else:
            tone = policy.get("tone") or "warm, concise, no jargon"
            numbered = [str(i + 1) + ". " + t for i, t in enumerate(offered_display)]
            try:
                drafted = api.ai.extract(
                    prompt=AI_PROMPT,
                    input=json.dumps({
                        "patient_name": patient_name, "practice_name": practice.get("name") or "",
                        "cancelled_time": cancelled_display, "available_times": numbered, "tone": tone,
                    }),
                    schema_hint=AI_HINT,
                )
            except Exception:
                drafted = {}
            drafted = drafted if isinstance(drafted, dict) else {}
            subject = drafted.get("subject") or "Rebooking your appointment"
            body = drafted.get("body") or (
                "Hi " + patient_name + ",\n\nSorry you had to cancel your " + cancelled_display + " appointment. "
                "If you'd like to rebook, these times are open:\n\n" + "\n".join(numbered)
                + "\n\nJust reply with the number that suits and we'll book it in."
            )

            description = (
                "**Patient:** " + patient_name + "  \n"
                "**Cancelled appointment:** " + cancelled_display + "  \n"
                "**Email on file:** " + (email or "none on file") + "  \n"
                "**Times offered:** " + ", ".join(offered_display) + "  \n\n"
                "**Drafted subject:** " + subject + "  \n\n"
                "**Drafted message:**\n\n" + body + "\n\n"
                "_Once sent, the patient's reply is read automatically and the time they pick is booked "
                "(after re-checking it is still free). If you edit the message, keep the numbered times as they are._"
            )
            if not email:
                description += "\n\n_No email on file for this patient - \"Send as drafted\" won't be able to send._"

            workq_item = api.workq.create(
                title="Cancellation reschedule offer: " + patient_name,
                scope="org",
                description=description,
                priority="normal",
                assignee_ids=[reviewer] if reviewer else None,
                labels=["healthcare-practice-management", "cancellation"],
            )
            workq_id = workq_item["id"]
            api.workq.attach_form(todo_id=workq_id, form_id=params["approval_form"])

            write_json("PracticeManager/Drafts/" + workq_id + ".json", {
                "kind": "reschedule_offer",
                "slug": slug,
                "appointment_id": appointment_id,
                "patient_id": patient_id,
                "patient_name": patient_name,
                "email": email,
                "subject": subject,
                "body": body,
                "practitioner_id": practitioner_id,
                "business_id": business_id,
                "appointment_type_id": appointment_type_id,
                "cancelled_starts_at": item.get("starts_at") or "",
                "cancelled_ends_at": item.get("ends_at") or "",
                "offered_times": offered,
                "offered_display": offered_display,
            })
            audit(slug, tz, "drafted", {"kind": "appointment", "id": appointment_id},
                  "Drafted a reschedule offer to " + patient_name + " after their cancellation",
                  workq_id,
                  [{"rule": "patient_facing_requires_approval", "result": "pass", "detail": "routed to WorkQ for approval before send"}])
            outcome = "requested_approval"
